import io
import os
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


class ValidationError(ValueError):
    pass


def _read_file_bytes(file_path: str) -> bytes:
    if not file_path or not os.path.isfile(file_path):
        raise ValidationError(f"File not found: {file_path}")
    with open(file_path, "rb") as f:
        return f.read()


def _field_value_to_python(field: Any) -> Any:
    if field is None:
        return None

    for attr in (
        "value_string",
        "value_currency",
        "value_date",
        "value_time",
        "value_phone_number",
        "value_integer",
        "value_number",
        "value_selection_mark",
        "value_signature",
        "value_boolean",
        "value_array",
        "value_object",
        "content",
    ):
        if hasattr(field, attr):
            value = getattr(field, attr)
            if value is not None:
                if attr == "value_currency":
                    return {
                        "amount": getattr(value, "amount", None),
                        "currency_symbol": getattr(value, "currency_symbol", None),
                        "currency_code": getattr(value, "currency_code", None),
                    }
                if attr == "value_array":
                    return [_field_value_to_python(item) for item in value]
                if attr == "value_object":
                    out = {}
                    for k, v in value.items():
                        out[k] = _field_value_to_python(v)
                    return out
                return value
    return None


def _extract_field(fields: Dict[str, Any], name: str) -> Dict[str, Any]:
    field = fields.get(name)
    if field is None:
        return {
            "present": False,
            "value": None,
            "confidence": None,
            "valid": False,
            "errors": [f"Missing required field: {name}"],
        }

    confidence = getattr(field, "confidence", None)
    value = _field_value_to_python(field)

    return {
        "present": True,
        "value": value,
        "confidence": confidence,
        "valid": True,
        "errors": [],
    }


def _validate_field(
    extracted: Dict[str, Any],
    name: str,
    min_confidence: float,
    allow_empty_string: bool = False,
) -> Dict[str, Any]:
    errors: List[str] = list(extracted["errors"])

    if not extracted["present"]:
        extracted["valid"] = False
        return extracted

    value = extracted["value"]
    confidence = extracted["confidence"]

    if value is None:
        errors.append(f"Field {name} has no value")
    elif isinstance(value, str) and not allow_empty_string and not value.strip():
        errors.append(f"Field {name} is empty")

    if confidence is None:
        errors.append(f"Field {name} has no confidence score")
    elif confidence < min_confidence:
        errors.append(
            f"Field {name} confidence {confidence:.3f} is below threshold {min_confidence:.3f}"
        )

    extracted["errors"] = errors
    extracted["valid"] = len(errors) == 0
    return extracted


def validate_invoice_fields(
    file_path: str,
    required_fields: List[str],
    min_confidence: float = 0.8,
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = api_key or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint:
        raise ValidationError("Missing Azure endpoint: AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    if not api_key:
        raise ValidationError("Missing Azure API key: AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not required_fields:
        raise ValidationError("required_fields must not be empty")
    if not (0.0 <= min_confidence <= 1.0):
        raise ValidationError("min_confidence must be between 0.0 and 1.0")

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    document_bytes = _read_file_bytes(file_path)

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=io.BytesIO(document_bytes),
    )
    result = poller.result()

    if not getattr(result, "documents", None):
        raise ValidationError("No documents were extracted from the invoice")

    doc = result.documents[0]
    fields = getattr(doc, "fields", {}) or {}

    validated_fields: Dict[str, Dict[str, Any]] = {}
    all_valid = True

    for field_name in required_fields:
        extracted = _extract_field(fields, field_name)
        validated = _validate_field(extracted, field_name, min_confidence)
        validated_fields[field_name] = validated
        if not validated["valid"]:
            all_valid = False

    return {
        "provider": "azure-document-intelligence",
        "model_id": "prebuilt-invoice",
        "document_type": getattr(doc, "doc_type", None),
        "document_confidence": getattr(doc, "confidence", None),
        "all_required_fields_valid": all_valid,
        "required_fields": validated_fields,
    }
